const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  // url      = env(\"DATABASE_URL\")\n}\n\n// ============================================================================\n// ENUMS DEL DOMINIO\n// ============================================================================\n\nenum RoleCode {\n  ADMIN_GERENCIA\n  CONTADOR_TESORERIA\n  CAJERO\n  VENDEDOR_MOSTRADOR\n  BODEGUERO\n  DESPACHADOR_LOGISTICA\n}\n\nenum WarehouseType {\n  MOSTRADOR\n  ALMACEN_CERRADO\n  PATIO_GRANELES\n  CUARENTENA_AVERIAS\n  CUSTODIA_VIRTUAL\n  EN_TRANSITO_VIRTUAL\n}\n\nenum FiscalDocumentType {\n  FACTURA_ELECTRONICA\n  TIRILLA_POS\n  FACTURA_CONTINGENCIA\n  NOTA_CREDITO\n  NOTA_DEBITO\n  REMISION\n  RECIBO_CAJA\n  ORDEN_COMPRA\n  VALE_CUSTODIA\n  TRASLADO\n}\n\nenum KardexMovementType {\n  COMPRA_RECEPCION\n  VENTA_POS\n  VENTA_CUSTODIA_RESERVA\n  ENTREGA_CUSTODIA\n  CANCELACION_CUSTODIA\n  DEVOLUCION_VENTA_VENDIBLE\n  DEVOLUCION_VENTA_AVERIA\n  DEVOLUCION_PROVEEDOR\n  TRASLADO_SALIDA\n  TRASLADO_ENTRADA\n  FRACCIONAMIENTO_SALIDA\n  FRACCIONAMIENTO_ENTRADA\n  MERMA_CORTE\n  AJUSTE_POSITIVO\n  AJUSTE_NEGATIVO\n  KIT_EXPLOSION_SALIDA\n}\n\nenum PurchaseOrderStatus {\n  BORRADOR\n  APROBADA\n  PARCIALMENTE_RECIBIDA\n  RECIBIDA\n  ANULADA\n}\n\nenum GoodsReceiptStatus {\n  BORRADOR\n  CON_DISCREPANCIA\n  APROBADA\n  ANULADA\n}\n\nenum TransferStatus {\n  EN_TRANSITO\n  RECIBIDO_COMPLETO\n  RECIBIDO_CON_FALTANTE\n  ANULADO\n}\n\nenum CycleCountStatus {\n  ABIERTO\n  RECONTEO_REQUERIDO\n  PENDIENTE_APROBACION\n  CERRADO\n}\n\nenum CustomerSegment {\n  MOSTRADOR\n  MAYORISTA\n  CONTRATISTA\n  CONVENIO\n}\n\nenum InvoiceDeliveryMode {\n  RETIRO_INMEDIATO\n  DESPACHO_DOMICILIO\n  ENTREGA_PARCIAL_CUSTODIA\n}\n\nenum InvoiceStatus {\n  EMITIDA_LOCAL\n  TRANSMITIDA_DIAN\n  CONTINGENCIA_PENDIENTE\n  ANULADA_PRE_TRANSMISION\n  CON_NOTA_CREDITO_PARCIAL\n  CON_NOTA_CREDITO_TOTAL\n}\n\nenum DispatchStatus {\n  PENDIENTE_ALISTAMIENTO\n  EN_ALISTAMIENTO\n  CARGADO\n  EN_RUTA\n  ENTREGADO\n  ENTREGA_PARCIAL\n  RECHAZADO\n}\n\nenum PaymentMethod {\n  EFECTIVO\n  TARJETA_DEBITO\n  TARJETA_CREDITO\n  TRANSFERENCIA\n  CHEQUE\n  CREDITO_INTERNO\n  SALDO_A_FAVOR\n}\n\nenum CashShiftStatus {\n  ABIERTO\n  CERRADO\n}\n\nenum CommissionBasis {\n  VENTA_FACTURADA\n  VENTA_RECAUDADA\n}\n\nenum PayrollStatus {\n  PRE_NOMINA\n  CERRADA\n}\n\nenum FraudSeverity {\n  MEDIA\n  ALTA\n  CRITICA\n}\n\n// ============================================================================\n// MÓDULO 1: CONFIGURACIÓN, SEGURIDAD (RBAC), SEDES Y PARÁMETROS FISCALES\n// ============================================================================\n\nmodel Branch {\n  id        String   @id @default(uuid()) @db.Uuid\n  code      String   @unique @db.VarChar(20)\n  name      String   @db.VarChar(120)\n  address   String   @db.VarChar(250)\n  city      String   @db.VarChar(80)\n  phone     String?  @db.VarChar(30)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  warehouses        Warehouse[]\n  posTerminals      PosTerminal[]\n  users             User[]\n  fiscalResolutions FiscalResolution[]\n  invoices          Invoice[]\n  cashShifts        CashShift[]\n  expenses          Expense[]\n  employees         Employee[]\n\n  @@map(\"branches\")\n}\n\nmodel Warehouse {\n  id                String        @id @default(uuid()) @db.Uuid\n  branchId          String        @db.Uuid\n  code              String        @unique @db.VarChar(25)\n  name              String        @db.VarChar(120)\n  type              WarehouseType\n  allowsDirectSales Boolean       @default(false)\n  allowsDispatch    Boolean       @default(true)\n  allowsReceiving   Boolean       @default(false)\n  isActive          Boolean       @default(true)\n  createdAt         DateTime      @default(now())\n  updatedAt         DateTime      @updatedAt\n\n  branch             Branch              @relation(fields: [branchId], references: [id])\n  locations          WarehouseLocation[]\n  inventoryBalances  InventoryBalance[]\n  kardexMovements    KardexMovement[]\n  purchaseOrders     PurchaseOrder[]\n  goodsReceipts      GoodsReceipt[]\n  transfersOut       StockTransfer[]     @relation(\"TransferOrigin\")\n  transfersIn        StockTransfer[]     @relation(\"TransferDestination\")\n  cycleCounts        CycleCount[]\n  defaultForTerminal PosTerminal[]\n\n  @@index([branchId, type])\n  @@map(\"warehouses\")\n}\n\nmodel WarehouseLocation {\n  id          String  @id @default(uuid()) @db.Uuid\n  warehouseId String  @db.Uuid\n  zone        String  @db.VarChar(20)\n  aisle       String  @db.VarChar(20)\n  rack        String  @db.VarChar(20)\n  level       String  @db.VarChar(20)\n  barcode     String  @unique @db.VarChar(60)\n  isActive    Boolean @default(true)\n\n  warehouse Warehouse                  @relation(fields: [warehouseId], references: [id])\n  skuLinks  ProductWarehouseLocation[]\n\n  @@unique([warehouseId, zone, aisle, rack, level])\n  @@map(\"warehouse_locations\")\n}\n\nmodel Role {\n  id                  String   @id @default(uuid()) @db.Uuid\n  code                RoleCode @unique\n  name                String   @db.VarChar(80)\n  canViewCosts        Boolean  @default(false) // Enmascaramiento (*)\n  canViewCashExpected Boolean  @default(false) // Arqueo ciego (*)\n  canApproveOverride  Boolean  @default(false) // Habilita PIN supervisor\n  createdAt           DateTime @default(now())\n\n  permissions RolePermission[]\n  users       User[]\n\n  @@map(\"roles\")\n}\n\nmodel Permission {\n  id          String @id @default(uuid()) @db.Uuid\n  resource    String @db.VarChar(60) // ej: \"inventory.catalog\", \"pos.invoice\"\n  action      String @db.VarChar(10) // \"L\", \"C\", \"E\", \"A\", \"N\"\n  description String @db.VarChar(200)\n\n  roles RolePermission[]\n\n  @@unique([resource, action])\n  @@map(\"permissions\")\n}\n\nmodel RolePermission {\n  roleId          String  @db.Uuid\n  permissionId    String  @db.Uuid\n  ownRecordsOnly  Boolean @default(false) // Restricción (*) a registros propios\n  maskedSensitive Boolean @default(false) // Restricción (*) sin costos/saldos\n\n  role       Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@id([roleId, permissionId])\n  @@map(\"role_permissions\")\n}\n\nmodel User {\n  id                String    @id @default(uuid()) @db.Uuid\n  branchId          String    @db.Uuid\n  roleId            String    @db.Uuid\n  username          String    @unique @db.VarChar(50)\n  email             String    @unique @db.VarChar(120)\n  fullName          String    @db.VarChar(140)\n  passwordHash      String    @db.VarChar(255) // Argon2id\n  supervisorPinHash String?   @db.VarChar(255) // Argon2id para PIN dinámico\n  allowedWorkStart  String?   @db.VarChar(5) // \"06:00\"\n  allowedWorkEnd    String?   @db.VarChar(5) // \"20:00\"\n  isActive          Boolean   @default(true)\n  failedLoginCount  Int       @default(0)\n  lockedUntil       DateTime?\n  lastActivityAt    DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  branch             Branch                  @relation(fields: [branchId], references: [id])\n  role               Role                    @relation(fields: [roleId], references: [id])\n  overridesRequested SupervisorOverrideLog[] @relation(\"OverrideRequester\")\n  overridesApproved  SupervisorOverrideLog[] @relation(\"OverrideApprover\")\n  cashShifts         CashShift[]\n  kardexMovements    KardexMovement[]\n  invoicesAsCashier  Invoice[]               @relation(\"InvoiceCashier\")\n  invoicesAsSeller   Invoice[]               @relation(\"InvoiceSeller\")\n  auditLogs          AuditLog[]\n  employee           Employee?\n\n  @@index([branchId, isActive])\n  @@map(\"users\")\n}\n\nmodel SupervisorOverrideLog {\n  id            String    @id @default(uuid()) @db.Uuid\n  requesterId   String    @db.Uuid\n  approverId    String    @db.Uuid\n  actionCode    String    @db.VarChar(60)\n  reason        String    @db.VarChar(250)\n  referenceType String    @db.VarChar(60)\n  referenceId   String    @db.VarChar(80)\n  usedAt        DateTime?\n  expiresAt     DateTime\n  createdAt     DateTime  @default(now())\n\n  requester User @relation(\"OverrideRequester\", fields: [requesterId], references: [id])\n  approver  User @relation(\"OverrideApprover\", fields: [approverId], references: [id])\n\n  @@index([requesterId, createdAt])\n  @@index([approverId, createdAt])\n  @@map(\"supervisor_override_logs\")\n}\n\nmodel TaxRule {\n  id            String   @id @default(uuid()) @db.Uuid\n  code          String   @unique @db.VarChar(30) // ej: \"IVA_19\", \"IVA_5\", \"IVA_0\", \"RETEFUENTE_2_5\"\n  name          String   @db.VarChar(100)\n  taxType       String   @db.VarChar(30) // IVA, RETEFUENTE, RETEICA, INC\n  ratePercent   Decimal  @db.Decimal(7, 4)\n  minBaseAmount Decimal  @default(0) @db.Decimal(18, 4)\n  isRetention   Boolean  @default(false)\n  isActive      Boolean  @default(true)\n  createdAt     DateTime @default(now())\n\n  products Product[]\n\n  @@map(\"tax_rules\")\n}\n\nmodel FiscalResolution {\n  id               String             @id @default(uuid()) @db.Uuid\n  branchId         String             @db.Uuid\n  documentType     FiscalDocumentType\n  resolutionNumber String             @db.VarChar(60)\n  prefix           String             @db.VarChar(15)\n  rangeStart       BigInt\n  rangeEnd         BigInt\n  currentNumber    BigInt\n  validFrom        DateTime\n  validUntil       DateTime\n  isContingency    Boolean            @default(false)\n  isActive         Boolean            @default(true)\n  createdAt        DateTime           @default(now())\n  updatedAt        DateTime           @updatedAt\n\n  branch         Branch        @relation(fields: [branchId], references: [id])\n  posTerminals   PosTerminal[] @relation(\"PrimaryResolution\")\n  contingencyFor PosTerminal[] @relation(\"ContingencyResolution\")\n\n  @@unique([branchId, prefix, documentType])\n  @@map(\"fiscal_resolutions\")\n}\n\nmodel PosTerminal {\n  id                      String   @id @default(uuid()) @db.Uuid\n  branchId                String   @db.Uuid\n  defaultWarehouseId      String   @db.Uuid\n  primaryResolutionId     String?  @db.Uuid\n  contingencyResolutionId String?  @db.Uuid\n  code                    String   @unique @db.VarChar(30)\n  name                    String   @db.VarChar(100)\n  maxCashAllowed          Decimal  @db.Decimal(18, 4)\n  thermalPrinterConfig    Json?\n  laserPrinterConfig      Json?\n  scaleSerialConfig       Json?\n  isActive                Boolean  @default(true)\n  createdAt               DateTime @default(now())\n\n  branch                Branch            @relation(fields: [branchId], references: [id])\n  defaultWarehouse      Warehouse         @relation(fields: [defaultWarehouseId], references: [id])\n  primaryResolution     FiscalResolution? @relation(\"PrimaryResolution\", fields: [primaryResolutionId], references: [id])\n  contingencyResolution FiscalResolution? @relation(\"ContingencyResolution\", fields: [contingencyResolutionId], references: [id])\n  cashShifts            CashShift[]\n  drawerEvents          CashDrawerEvent[]\n\n  @@map(\"pos_terminals\")\n}\n\nmodel CashDrawerEvent {\n  id           String   @id @default(uuid()) @db.Uuid\n  terminalId   String   @db.Uuid\n  userId       String   @db.Uuid\n  shiftId      String?  @db.Uuid\n  reason       String   @db.VarChar(120) // SALE, REFUND, MANUAL_OVERRIDE, ANOMALOUS\n  isAuthorized Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  terminal PosTerminal @relation(fields: [terminalId], references: [id])\n\n  @@index([terminalId, createdAt])\n  @@map(\"cash_drawer_events\")\n}\n\nmodel AccountingPeriod {\n  id        String    @id @default(uuid()) @db.Uuid\n  year      Int\n  month     Int\n  isClosed  Boolean   @default(false)\n  closedBy  String?   @db.Uuid\n  closedAt  DateTime?\n  createdAt DateTime  @default(now())\n\n  @@unique([year, month])\n  @@map(\"accounting_periods\")\n}\n\n// ============================================================================\n// MÓDULO 2: INVENTARIO, MOTOR DE UM, KITS, COMPRAS Y KARDEX\n// ============================================================================\n\nmodel Category {\n  id                  String   @id @default(uuid()) @db.Uuid\n  parentId            String?  @db.Uuid\n  code                String   @unique @db.VarChar(30)\n  name                String   @db.VarChar(100)\n  maxShrinkagePercent Decimal  @default(0) @db.Decimal(5, 2) // CB-05 Tope merma corte\n  minMarginPercent    Decimal  @default(10) @db.Decimal(5, 2)\n  createdAt           DateTime @default(now())\n\n  parent   Category?  @relation(\"CategoryTree\", fields: [parentId], references: [id])\n  children Category[] @relation(\"CategoryTree\")\n  products Product[]\n\n  @@map(\"categories\")\n}\n\nmodel Brand {\n  id       String    @id @default(uuid()) @db.Uuid\n  name     String    @unique @db.VarChar(80)\n  products Product[]\n\n  @@map(\"brands\")\n}\n\nmodel UnitOfMeasure {\n  id            String  @id @default(uuid()) @db.Uuid\n  code          String  @unique @db.VarChar(15) // UND, M, CM, G, KG, ML, L, TON, M3, BTO, RLL\n  name          String  @db.VarChar(60)\n  allowDecimals Boolean @default(false)\n\n  baseProducts Product[]               @relation(\"BaseUom\")\n  conversions  ProductUnitConversion[]\n\n  @@map(\"units_of_measure\")\n}\n\nmodel Product {\n  id               String   @id @default(uuid()) @db.Uuid\n  sku              String   @unique @db.VarChar(40)\n  manufacturerRef  String?  @db.VarChar(60)\n  name             String   @db.VarChar(200)\n  description      String?  @db.Text\n  categoryId       String   @db.Uuid\n  brandId          String?  @db.Uuid\n  baseUomId        String   @db.Uuid\n  taxRuleId        String   @db.Uuid\n  specs            Json? // calibre, diámetro, amperaje, etc.\n  weightKg         Decimal  @default(0) @db.Decimal(12, 4) // Para cálculo de fletes (RF-16)\n  volumeM3         Decimal  @default(0) @db.Decimal(12, 6)\n  baseSalePrice    Decimal  @db.Decimal(18, 4)\n  minMarginPercent Decimal? @db.Decimal(5, 2) // Sobrescribe categoría\n  isKit            Boolean  @default(false)\n  requiresSerial   Boolean  @default(false) // Maquinaria pesada\n  isCuttable       Boolean  @default(false) // Habilita merma por corte\n  isWeighable      Boolean  @default(false) // Lectura desde báscula\n  isActive         Boolean  @default(true)\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  category          Category                   @relation(fields: [categoryId], references: [id])\n  brand             Brand?                     @relation(fields: [brandId], references: [id])\n  baseUom           UnitOfMeasure              @relation(\"BaseUom\", fields: [baseUomId], references: [id])\n  taxRule           TaxRule                    @relation(fields: [taxRuleId], references: [id])\n  barcodes          ProductBarcode[]\n  unitConversions   ProductUnitConversion[]\n  locations         ProductWarehouseLocation[]\n  kitComponents     ProductKitItem[]           @relation(\"KitParent\")\n  partOfKits        ProductKitItem[]           @relation(\"KitComponent\")\n  substitutes       ProductRelation[]          @relation(\"ProductSource\")\n  relatedBy         ProductRelation[]          @relation(\"ProductTarget\")\n  inventoryBalances InventoryBalance[]\n  kardexMovements   KardexMovement[]\n  serials           ProductSerial[]\n  priceListItems    PriceListItem[]\n  purchaseItems     PurchaseOrderItem[]\n  receiptItems      GoodsReceiptItem[]\n  invoiceItems      InvoiceItem[]\n  creditNoteItems   CreditNoteItem[]\n\n  @@index([name])\n  @@index([categoryId, isActive])\n  @@map(\"products\")\n}\n\nmodel ProductBarcode {\n  id               String  @id @default(uuid()) @db.Uuid\n  productId        String  @db.Uuid\n  unitConversionId String? @db.Uuid\n  barcode          String  @unique @db.VarChar(80)\n  isPrimary        Boolean @default(false)\n\n  product        Product                @relation(fields: [productId], references: [id], onDelete: Cascade)\n  unitConversion ProductUnitConversion? @relation(fields: [unitConversionId], references: [id])\n\n  @@index([productId])\n  @@map(\"product_barcodes\")\n}\n\nmodel ProductUnitConversion {\n  id             String   @id @default(uuid()) @db.Uuid\n  productId      String   @db.Uuid\n  uomId          String   @db.Uuid\n  factorToBase   Decimal  @db.Decimal(18, 6) // Ej: 1 Rollo = 100.000000 metros\n  isPurchaseUnit Boolean  @default(false)\n  isSaleUnit     Boolean  @default(true)\n  overridePrice  Decimal? @db.Decimal(18, 4)\n\n  product  Product          @relation(fields: [productId], references: [id], onDelete: Cascade)\n  uom      UnitOfMeasure    @relation(fields: [uomId], references: [id])\n  barcodes ProductBarcode[]\n\n  @@unique([productId, uomId])\n  @@map(\"product_unit_conversions\")\n}\n\nmodel ProductWarehouseLocation {\n  productId  String  @db.Uuid\n  locationId String  @db.Uuid\n  isPrimary  Boolean @default(true)\n\n  product  Product           @relation(fields: [productId], references: [id], onDelete: Cascade)\n  location WarehouseLocation @relation(fields: [locationId], references: [id], onDelete: Cascade)\n\n  @@id([productId, locationId])\n  @@map(\"product_warehouse_locations\")\n}\n\nmodel ProductKitItem {\n  id               String  @id @default(uuid()) @db.Uuid\n  kitProductId     String  @db.Uuid\n  componentId      String  @db.Uuid\n  quantityInBase   Decimal @db.Decimal(18, 4)\n  priceWeightRatio Decimal @db.Decimal(7, 6) // Para prorrateo de venta (RF-07)\n\n  kitProduct Product @relation(\"KitParent\", fields: [kitProductId], references: [id], onDelete: Cascade)\n  component  Product @relation(\"KitComponent\", fields: [componentId], references: [id])\n\n  @@unique([kitProductId, componentId])\n  @@map(\"product_kit_items\")\n}\n\nmodel ProductRelation {\n  sourceProductId String @db.Uuid\n  targetProductId String @db.Uuid\n  relationType    String @db.VarChar(20) // SUBSTITUTE, COMPLEMENTARY\n\n  source Product @relation(\"ProductSource\", fields: [sourceProductId], references: [id], onDelete: Cascade)\n  target Product @relation(\"ProductTarget\", fields: [targetProductId], references: [id], onDelete: Cascade)\n\n  @@id([sourceProductId, targetProductId, relationType])\n  @@map(\"product_relations\")\n}\n\n// INVENTARIO TRIDIMENSIONAL (Bloqueado con FOR UPDATE en CB-04)\nmodel InventoryBalance {\n  id           String   @id @default(uuid()) @db.Uuid\n  productId    String   @db.Uuid\n  warehouseId  String   @db.Uuid\n  physicalQty  Decimal  @default(0) @db.Decimal(18, 4) // availableQty + custodyQty\n  availableQty Decimal  @default(0) @db.Decimal(18, 4) // Libre para venta\n  custodyQty   Decimal  @default(0) @db.Decimal(18, 4) // Facturado pendiente retiro\n  inTransitQty Decimal  @default(0) @db.Decimal(18, 4) // Traslados en camino\n  averageCost  Decimal  @default(0) @db.Decimal(18, 4) // CPP vigente\n  minStock     Decimal  @default(0) @db.Decimal(18, 4)\n  maxStock     Decimal  @default(0) @db.Decimal(18, 4)\n  salesBlocked Boolean  @default(false) // CB-02 Stock fantasma\n  updatedAt    DateTime @updatedAt\n\n  product   Product   @relation(fields: [productId], references: [id])\n  warehouse Warehouse @relation(fields: [warehouseId], references: [id])\n\n  @@unique([productId, warehouseId])\n  @@index([warehouseId, salesBlocked])\n  @@map(\"inventory_balances\")\n}\n\nmodel ProductSerial {\n  id             String    @id @default(uuid()) @db.Uuid\n  productId      String    @db.Uuid\n  warehouseId    String?   @db.Uuid\n  serialNumber   String    @unique @db.VarChar(100)\n  status         String    @db.VarChar(25) // IN_STOCK, SOLD, WARRANTY, RETURNED\n  goodsReceiptId String?   @db.Uuid\n  invoiceId      String?   @db.Uuid\n  warrantyUntil  DateTime?\n  createdAt      DateTime  @default(now())\n\n  product Product @relation(fields: [productId], references: [id])\n\n  @@index([productId, status])\n  @@map(\"product_serials\")\n}\n\n// KARDEX INMUTABLE (Protegido con trigger SQL)\nmodel KardexMovement {\n  id             String             @id @default(uuid()) @db.Uuid\n  productId      String             @db.Uuid\n  warehouseId    String             @db.Uuid\n  movementType   KardexMovementType\n  quantityDelta  Decimal            @db.Decimal(18, 4) // + entrada, - salida\n  previousQty    Decimal            @db.Decimal(18, 4)\n  newQty         Decimal            @db.Decimal(18, 4)\n  unitCost       Decimal            @db.Decimal(18, 4)\n  totalCost      Decimal            @db.Decimal(18, 4)\n  documentType   String             @db.VarChar(40)\n  documentId     String             @db.Uuid\n  documentNumber String             @db.VarChar(60)\n  userId         String             @db.Uuid\n  notes          String?            @db.VarChar(250)\n  createdAt      DateTime           @default(now())\n\n  product   Product   @relation(fields: [productId], references: [id])\n  warehouse Warehouse @relation(fields: [warehouseId], references: [id])\n  user      User      @relation(fields: [userId], references: [id])\n\n  @@index([productId, warehouseId, createdAt])\n  @@index([documentType, documentId])\n  @@map(\"kardex_movements\")\n}\n\nmodel Supplier {\n  id               String   @id @default(uuid()) @db.Uuid\n  taxId            String   @unique @db.VarChar(30)\n  businessName     String   @db.VarChar(160)\n  contactName      String?  @db.VarChar(120)\n  email            String?  @db.VarChar(120)\n  phone            String?  @db.VarChar(40)\n  paymentTermDays  Int      @default(30)\n  leadTimeDays     Int      @default(5)\n  earlyPayDiscount Decimal  @default(0) @db.Decimal(5, 2)\n  isActive         Boolean  @default(true)\n  createdAt        DateTime @default(now())\n\n  purchaseOrders  PurchaseOrder[]\n  accountsPayable AccountPayable[]\n\n  @@map(\"suppliers\")\n}\n\nmodel PurchaseOrder {\n  id          String              @id @default(uuid()) @db.Uuid\n  orderNumber String              @unique @db.VarChar(40)\n  supplierId  String              @db.Uuid\n  warehouseId String              @db.Uuid\n  status      PurchaseOrderStatus @default(BORRADOR)\n  expectedAt  DateTime?\n  subtotal    Decimal             @db.Decimal(18, 4)\n  taxTotal    Decimal             @db.Decimal(18, 4)\n  total       Decimal             @db.Decimal(18, 4)\n  createdBy   String              @db.Uuid\n  approvedBy  String?             @db.Uuid\n  createdAt   DateTime            @default(now())\n\n  supplier      Supplier            @relation(fields: [supplierId], references: [id])\n  warehouse     Warehouse           @relation(fields: [warehouseId], references: [id])\n  items         PurchaseOrderItem[]\n  goodsReceipts GoodsReceipt[]\n\n  @@map(\"purchase_orders\")\n}\n\nmodel PurchaseOrderItem {\n  id              String  @id @default(uuid()) @db.Uuid\n  purchaseOrderId String  @db.Uuid\n  productId       String  @db.Uuid\n  uomCode         String  @db.VarChar(15)\n  factorToBase    Decimal @db.Decimal(18, 6)\n  orderedQty      Decimal @db.Decimal(18, 4) // Oculto al bodeguero (recepción ciega)\n  receivedQty     Decimal @default(0) @db.Decimal(18, 4)\n  unitPrice       Decimal @db.Decimal(18, 4)\n\n  purchaseOrder PurchaseOrder @relation(fields: [purchaseOrderId], references: [id], onDelete: Cascade)\n  product       Product       @relation(fields: [productId], references: [id])\n\n  @@map(\"purchase_order_items\")\n}\n\nmodel GoodsReceipt {\n  id                 String             @id @default(uuid()) @db.Uuid\n  receiptNumber      String             @unique @db.VarChar(40)\n  purchaseOrderId    String             @db.Uuid\n  warehouseId        String             @db.Uuid\n  supplierInvoiceNum String             @db.VarChar(60)\n  freightCost        Decimal            @default(0) @db.Decimal(18, 4) // Prorrateado al CPP\n  insuranceCost      Decimal            @default(0) @db.Decimal(18, 4)\n  status             GoodsReceiptStatus @default(BORRADOR)\n  hasDiscrepancies   Boolean            @default(false)\n  receivedBy         String             @db.Uuid\n  approvedBy         String?            @db.Uuid\n  createdAt          DateTime           @default(now())\n\n  purchaseOrder PurchaseOrder      @relation(fields: [purchaseOrderId], references: [id])\n  warehouse     Warehouse          @relation(fields: [warehouseId], references: [id])\n  items         GoodsReceiptItem[]\n\n  @@map(\"goods_receipts\")\n}\n\nmodel GoodsReceiptItem {\n  id                String  @id @default(uuid()) @db.Uuid\n  goodsReceiptId    String  @db.Uuid\n  productId         String  @db.Uuid\n  countedQtyInBase  Decimal @db.Decimal(18, 4) // Conteo ciego del bodeguero\n  damagedQtyInBase  Decimal @default(0) @db.Decimal(18, 4)\n  expectedQtyInBase Decimal @db.Decimal(18, 4) // Calculado en backend\n  landedUnitCost    Decimal @db.Decimal(18, 4) // Costo + flete/seguro prorrateado\n\n  goodsReceipt GoodsReceipt @relation(fields: [goodsReceiptId], references: [id], onDelete: Cascade)\n  product      Product      @relation(fields: [productId], references: [id])\n\n  @@map(\"goods_receipt_items\")\n}\n\nmodel StockTransfer {\n  id                String         @id @default(uuid()) @db.Uuid\n  transferNumber    String         @unique @db.VarChar(40)\n  originWarehouseId String         @db.Uuid\n  destWarehouseId   String         @db.Uuid\n  status            TransferStatus @default(EN_TRANSITO)\n  driverName        String?        @db.VarChar(120)\n  vehiclePlate      String?        @db.VarChar(20)\n  dispatchedBy      String         @db.Uuid\n  receivedBy        String?        @db.Uuid\n  dispatchedAt      DateTime       @default(now())\n  receivedAt        DateTime?\n\n  originWarehouse Warehouse           @relation(\"TransferOrigin\", fields: [originWarehouseId], references: [id])\n  destWarehouse   Warehouse           @relation(\"TransferDestination\", fields: [destWarehouseId], references: [id])\n  items           StockTransferItem[]\n\n  @@map(\"stock_transfers\")\n}\n\nmodel StockTransferItem {\n  id          String  @id @default(uuid()) @db.Uuid\n  transferId  String  @db.Uuid\n  productId   String  @db.Uuid\n  sentQty     Decimal @db.Decimal(18, 4)\n  receivedQty Decimal @default(0) @db.Decimal(18, 4)\n\n  transfer StockTransfer @relation(fields: [transferId], references: [id], onDelete: Cascade)\n\n  @@map(\"stock_transfer_items\")\n}\n\nmodel CycleCount {\n  id          String           @id @default(uuid()) @db.Uuid\n  countNumber String           @unique @db.VarChar(40)\n  warehouseId String           @db.Uuid\n  scope       String           @db.VarChar(120) // ABC_A, PASILLO, URGENTE_CB02\n  status      CycleCountStatus @default(ABIERTO)\n  createdBy   String           @db.Uuid\n  approvedBy  String?          @db.Uuid\n  createdAt   DateTime         @default(now())\n  closedAt    DateTime?\n\n  warehouse Warehouse        @relation(fields: [warehouseId], references: [id])\n  items     CycleCountItem[]\n\n  @@map(\"cycle_counts\")\n}\n\nmodel CycleCountItem {\n  id               String   @id @default(uuid()) @db.Uuid\n  cycleCountId     String   @db.Uuid\n  productId        String   @db.Uuid\n  frozenSystemQty  Decimal  @db.Decimal(18, 4) // Oculto al contador (conteo ciego)\n  firstCountQty    Decimal? @db.Decimal(18, 4)\n  secondCountQty   Decimal? @db.Decimal(18, 4)\n  adjustmentReason String?  @db.VarChar(60) // MERMA, ROTURA, ROBO, ERROR_DIGITACION\n\n  cycleCount CycleCount @relation(fields: [cycleCountId], references: [id], onDelete: Cascade)\n\n  @@map(\"cycle_count_items\")\n}\n\n// ============================================================================\n// MÓDULO 3: CLIENTES, VENTAS POS, CUSTODIA, DESPACHOS Y NOTAS CRÉDITO\n// ============================================================================\n\nmodel PriceList {\n  id       String          @id @default(uuid()) @db.Uuid\n  code     String          @unique @db.VarChar(30)\n  name     String          @db.VarChar(100)\n  segment  CustomerSegment\n  isActive Boolean         @default(true)\n\n  customers Customer[]\n  items     PriceListItem[]\n\n  @@map(\"price_lists\")\n}\n\nmodel PriceListItem {\n  id             String  @id @default(uuid()) @db.Uuid\n  priceListId    String  @db.Uuid\n  productId      String  @db.Uuid\n  minQuantity    Decimal @default(1) @db.Decimal(18, 4)\n  unitPrice      Decimal @db.Decimal(18, 4)\n  maxDiscountPct Decimal @default(0) @db.Decimal(5, 2)\n\n  priceList PriceList @relation(fields: [priceListId], references: [id], onDelete: Cascade)\n  product   Product   @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([priceListId, productId, minQuantity])\n  @@map(\"price_list_items\")\n}\n\nmodel Customer {\n  id                  String          @id @default(uuid()) @db.Uuid\n  taxId               String          @unique @db.VarChar(30)\n  fullName            String          @db.VarChar(160)\n  segment             CustomerSegment @default(MOSTRADOR)\n  priceListId         String?         @db.Uuid\n  email               String?         @db.VarChar(120)\n  phone               String?         @db.VarChar(40)\n  creditLimit         Decimal         @default(0) @db.Decimal(18, 4)\n  creditUsed          Decimal         @default(0) @db.Decimal(18, 4)\n  creditTermDays      Int             @default(0)\n  gracePeriodDays     Int             @default(5)\n  isBlockedForOverdue Boolean         @default(false)\n  authorizedPickups   Json? // Lista de cédulas/nombres autorizados a retirar\n  deliveryAddresses   Json?\n  advanceBalance      Decimal         @default(0) @db.Decimal(18, 4) // Anticipos / Saldo a favor\n  isActive            Boolean         @default(true)\n  createdAt           DateTime        @default(now())\n  updatedAt           DateTime        @updatedAt\n\n  priceList          PriceList?          @relation(fields: [priceListId], references: [id])\n  quotes             Quote[]\n  invoices           Invoice[]\n  accountsReceivable AccountReceivable[]\n  receipts           CustomerReceipt[]\n\n  @@index([fullName])\n  @@map(\"customers\")\n}\n\nmodel Quote {\n  id          String   @id @default(uuid()) @db.Uuid\n  quoteNumber String   @unique @db.VarChar(40)\n  customerId  String   @db.Uuid\n  sellerId    String   @db.Uuid\n  projectName String?  @db.VarChar(150)\n  validUntil  DateTime\n  status      String   @db.VarChar(25) // VIGENTE, CONVERTIDA, VENCIDA, CANCELADA\n  total       Decimal  @db.Decimal(18, 4)\n  itemsJson   Json\n  createdAt   DateTime @default(now())\n\n  customer Customer @relation(fields: [customerId], references: [id])\n\n  @@map(\"quotes\")\n}\n\nmodel Invoice {\n  id             String              @id @default(uuid()) @db.Uuid\n  idempotencyKey String              @unique @db.VarChar(80) // Clave para cola offline (CB-01)\n  branchId       String              @db.Uuid\n  terminalId     String              @db.Uuid\n  cashShiftId    String              @db.Uuid\n  customerId     String              @db.Uuid\n  sellerId       String              @db.Uuid\n  cashierId      String              @db.Uuid\n  prefix         String              @db.VarChar(15)\n  consecutive    BigInt\n  fullNumber     String              @unique @db.VarChar(40)\n  isContingency  Boolean             @default(false)\n  deliveryMode   InvoiceDeliveryMode @default(RETIRO_INMEDIATO)\n  status         InvoiceStatus       @default(EMITIDA_LOCAL)\n  subtotal       Decimal             @db.Decimal(18, 4)\n  discountTotal  Decimal             @default(0) @db.Decimal(18, 4)\n  taxTotal       Decimal             @db.Decimal(18, 4)\n  retentionTotal Decimal             @default(0) @db.Decimal(18, 4)\n  grandTotal     Decimal             @db.Decimal(18, 4)\n  cufe           String?             @db.VarChar(120) // Código fiscal electrónico\n  issuedAt       DateTime            @default(now())\n  createdAt      DateTime            @default(now())\n\n  branch          Branch                   @relation(fields: [branchId], references: [id])\n  cashShift       CashShift                @relation(fields: [cashShiftId], references: [id])\n  customer        Customer                 @relation(fields: [customerId], references: [id])\n  seller          User                     @relation(\"InvoiceSeller\", fields: [sellerId], references: [id])\n  cashier         User                     @relation(\"InvoiceCashier\", fields: [cashierId], references: [id])\n  items           InvoiceItem[]\n  payments        InvoicePayment[]\n  custodyVouchers CustodyDeliveryVoucher[]\n  dispatchOrders  DispatchOrder[]\n  creditNotes     CreditNote[]\n  receivable      AccountReceivable?\n\n  @@index([branchId, issuedAt])\n  @@index([customerId, issuedAt])\n  @@map(\"invoices\")\n}\n\nmodel InvoiceItem {\n  id                   String  @id @default(uuid()) @db.Uuid\n  invoiceId            String  @db.Uuid\n  productId            String  @db.Uuid\n  warehouseId          String  @db.Uuid\n  uomCode              String  @db.VarChar(15)\n  factorToBase         Decimal @db.Decimal(18, 6)\n  soldQty              Decimal @db.Decimal(18, 4)\n  soldQtyInBase        Decimal @db.Decimal(18, 4)\n  deliveredQtyInBase   Decimal @default(0) @db.Decimal(18, 4) // Control entregas parciales\n  custodyPendingInBase Decimal @default(0) @db.Decimal(18, 4) // Saldo en custodia (RF-15)\n  unitPrice            Decimal @db.Decimal(18, 4)\n  discountAmount       Decimal @default(0) @db.Decimal(18, 4)\n  taxRate              Decimal @db.Decimal(7, 4)\n  taxAmount            Decimal @db.Decimal(18, 4)\n  unitCostSnapshot     Decimal @db.Decimal(18, 4) // CPP congelado al vender (rentabilidad real)\n  lineTotal            Decimal @db.Decimal(18, 4)\n\n  invoice Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id])\n\n  @@map(\"invoice_items\")\n}\n\nmodel InvoicePayment {\n  id                String        @id @default(uuid()) @db.Uuid\n  invoiceId         String        @db.Uuid\n  method            PaymentMethod\n  amount            Decimal       @db.Decimal(18, 4)\n  bankName          String?       @db.VarChar(80)\n  referenceNumber   String?       @unique @db.VarChar(80) // Unicidad de comprobante (RF-18)\n  treasuryConfirmed Boolean       @default(true)\n  createdAt         DateTime      @default(now())\n\n  invoice Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@map(\"invoice_payments\")\n}\n\nmodel CustodyDeliveryVoucher {\n  id             String   @id @default(uuid()) @db.Uuid\n  voucherNumber  String   @unique @db.VarChar(40)\n  invoiceId      String   @db.Uuid\n  pickedUpByName String   @db.VarChar(140)\n  pickedUpByDoc  String   @db.VarChar(30)\n  signatureUrl   String?  @db.VarChar(255)\n  dispatchedBy   String   @db.Uuid\n  createdAt      DateTime @default(now())\n\n  invoice Invoice               @relation(fields: [invoiceId], references: [id])\n  items   CustodyDeliveryItem[]\n\n  @@map(\"custody_delivery_vouchers\")\n}\n\nmodel CustodyDeliveryItem {\n  id            String  @id @default(uuid()) @db.Uuid\n  voucherId     String  @db.Uuid\n  invoiceItemId String  @db.Uuid\n  productId     String  @db.Uuid\n  qtyInBase     Decimal @db.Decimal(18, 4)\n\n  voucher CustodyDeliveryVoucher @relation(fields: [voucherId], references: [id], onDelete: Cascade)\n\n  @@map(\"custody_delivery_items\")\n}\n\nmodel DispatchOrder {\n  id               String         @id @default(uuid()) @db.Uuid\n  orderNumber      String         @unique @db.VarChar(40)\n  invoiceId        String         @db.Uuid\n  deliveryAddress  String         @db.VarChar(250)\n  zone             String?        @db.VarChar(60)\n  totalWeightKg    Decimal        @default(0) @db.Decimal(12, 4)\n  totalVolumeM3    Decimal        @default(0) @db.Decimal(12, 6)\n  freightFee       Decimal        @default(0) @db.Decimal(18, 4)\n  vehiclePlate     String?        @db.VarChar(20)\n  driverName       String?        @db.VarChar(120)\n  status           DispatchStatus @default(PENDIENTE_ALISTAMIENTO)\n  gatePassToken    String         @unique @db.VarChar(80) // QR único de portería (CB-07)\n  gatePassBurnedAt DateTime? // Se sella al salir de patio\n  gateCheckedBy    String?        @db.Uuid\n  proofPhotoUrl    String?        @db.VarChar(255)\n  deliveredAt      DateTime?\n  createdAt        DateTime       @default(now())\n\n  invoice Invoice @relation(fields: [invoiceId], references: [id])\n\n  @@index([status, zone])\n  @@map(\"dispatch_orders\")\n}\n\nmodel CreditNote {\n  id                  String   @id @default(uuid()) @db.Uuid\n  creditNoteNumber    String   @unique @db.VarChar(40)\n  invoiceId           String   @db.Uuid\n  reason              String   @db.VarChar(200)\n  isCustodyCancelOnly Boolean  @default(false) // CB-06 sin reingreso físico\n  warehouseVerifiedBy String?  @db.Uuid // Inspección física obligatoria (RF-17)\n  approvedBy          String   @db.Uuid\n  refundDestination   String   @db.VarChar(30) // CARTERA, SALDO_A_FAVOR, EFECTIVO, TRANSFERENCIA\n  totalAmount         Decimal  @db.Decimal(18, 4)\n  createdAt           DateTime @default(now())\n\n  invoice Invoice          @relation(fields: [invoiceId], references: [id])\n  items   CreditNoteItem[]\n\n  @@map(\"credit_notes\")\n}\n\nmodel CreditNoteItem {\n  id              String  @id @default(uuid()) @db.Uuid\n  creditNoteId    String  @db.Uuid\n  productId       String  @db.Uuid\n  returnedQty     Decimal @db.Decimal(18, 4)\n  returnToDamaged Boolean @default(false)\n  unitRefund      Decimal @db.Decimal(18, 4)\n  lineTotal       Decimal @db.Decimal(18, 4)\n\n  creditNote CreditNote @relation(fields: [creditNoteId], references: [id], onDelete: Cascade)\n  product    Product    @relation(fields: [productId], references: [id])\n\n  @@map(\"credit_note_items\")\n}\n\n// ============================================================================\n// MÓDULO 4: CAJA CIEGA Y TESORERÍA\n// ============================================================================\n\nmodel CashShift {\n  id                String          @id @default(uuid()) @db.Uuid\n  branchId          String          @db.Uuid\n  terminalId        String          @db.Uuid\n  cashierId         String          @db.Uuid\n  status            CashShiftStatus @default(ABIERTO)\n  openingFloat      Decimal         @db.Decimal(18, 4)\n  declaredCash      Decimal?        @db.Decimal(18, 4) // Ingresado a ciegas por cajero\n  declaredCards     Decimal?        @db.Decimal(18, 4)\n  declaredTransfers Decimal?        @db.Decimal(18, 4)\n  declaredChecks    Decimal?        @db.Decimal(18, 4)\n  expectedCash      Decimal?        @db.Decimal(18, 4) // Calculado solo al sellar\n  expectedCards     Decimal?        @db.Decimal(18, 4)\n  expectedTransfers Decimal?        @db.Decimal(18, 4)\n  expectedChecks    Decimal?        @db.Decimal(18, 4)\n  cashDifference    Decimal?        @db.Decimal(18, 4)\n  openedAt          DateTime        @default(now())\n  closedAt          DateTime?\n\n  branch        Branch                  @relation(fields: [branchId], references: [id])\n  terminal      PosTerminal             @relation(fields: [terminalId], references: [id])\n  cashier       User                    @relation(fields: [cashierId], references: [id])\n  invoices      Invoice[]\n  drops         CashDrop[]\n  denominations CashCountDenomination[]\n\n  @@index([terminalId, status])\n  @@map(\"cash_shifts\")\n}\n\nmodel CashDrop {\n  id          String   @id @default(uuid()) @db.Uuid\n  cashShiftId String   @db.Uuid\n  amount      Decimal  @db.Decimal(18, 4)\n  destination String   @db.VarChar(60) // BOVEDA, CONSIGNACION, CAJA_MENOR\n  handedBy    String   @db.Uuid\n  receivedBy  String   @db.Uuid // Doble firma digital (RF-19)\n  createdAt   DateTime @default(now())\n\n  cashShift CashShift @relation(fields: [cashShiftId], references: [id])\n\n  @@map(\"cash_drops\")\n}\n\nmodel CashCountDenomination {\n  id           String  @id @default(uuid()) @db.Uuid\n  cashShiftId  String  @db.Uuid\n  denomination Decimal @db.Decimal(12, 2) // 100000, 50000, 20000, ..., 100\n  quantity     Int\n  subtotal     Decimal @db.Decimal(18, 4)\n\n  cashShift CashShift @relation(fields: [cashShiftId], references: [id], onDelete: Cascade)\n\n  @@map(\"cash_count_denominations\")\n}\n\nmodel CustomerReceipt {\n  id              String        @id @default(uuid()) @db.Uuid\n  receiptNumber   String        @unique @db.VarChar(40)\n  customerId      String        @db.Uuid\n  cashShiftId     String?       @db.Uuid\n  paymentMethod   PaymentMethod\n  amount          Decimal       @db.Decimal(18, 4)\n  retentionAmount Decimal       @default(0) @db.Decimal(18, 4)\n  isAdvance       Boolean       @default(false)\n  referenceNumber String?       @unique @db.VarChar(80)\n  createdBy       String        @db.Uuid\n  createdAt       DateTime      @default(now())\n\n  customer Customer @relation(fields: [customerId], references: [id])\n\n  @@map(\"customer_receipts\")\n}\n\n// ============================================================================\n// MÓDULO 5: INGRESOS, EGRESOS, CARTERA (CxC) Y PROVEEDORES (CxP)\n// ============================================================================\n\nmodel Expense {\n  id                 String   @id @default(uuid()) @db.Uuid\n  branchId           String   @db.Uuid\n  category           String   @db.VarChar(60)\n  costType           String   @db.VarChar(15) // FIJO, VARIABLE\n  thirdPartyTaxId    String   @db.VarChar(30)\n  thirdPartyName     String   @db.VarChar(140)\n  supplierInvoiceNum String   @db.VarChar(60)\n  sourceFund         String   @db.VarChar(30) // BANCO, CAJA_MENOR\n  amount             Decimal  @db.Decimal(18, 4)\n  taxAmount          Decimal  @default(0) @db.Decimal(18, 4)\n  supportFileUrl     String?  @db.VarChar(255)\n  createdBy          String   @db.Uuid\n  expenseDate        DateTime\n  createdAt          DateTime @default(now())\n\n  branch Branch @relation(fields: [branchId], references: [id])\n\n  @@unique([thirdPartyTaxId, supplierInvoiceNum]) // Impide factura duplicada (RF-22)\n  @@map(\"expenses\")\n}\n\nmodel AccountReceivable {\n  id             String   @id @default(uuid()) @db.Uuid\n  invoiceId      String   @unique @db.Uuid\n  customerId     String   @db.Uuid\n  originalAmount Decimal  @db.Decimal(18, 4)\n  balanceAmount  Decimal  @db.Decimal(18, 4)\n  dueDate        DateTime\n  status         String   @db.VarChar(20) // PENDIENTE, PARCIAL, PAGADA, VENCIDA\n  createdAt      DateTime @default(now())\n\n  invoice  Invoice  @relation(fields: [invoiceId], references: [id])\n  customer Customer @relation(fields: [customerId], references: [id])\n\n  @@index([customerId, status, dueDate])\n  @@map(\"accounts_receivable\")\n}\n\nmodel AccountPayable {\n  id                 String    @id @default(uuid()) @db.Uuid\n  supplierId         String    @db.Uuid\n  goodsReceiptId     String?   @db.Uuid\n  supplierInvoiceNum String    @db.VarChar(60)\n  originalAmount     Decimal   @db.Decimal(18, 4)\n  balanceAmount      Decimal   @db.Decimal(18, 4)\n  dueDate            DateTime\n  earlyPayDeadline   DateTime?\n  status             String    @db.VarChar(20) // PENDIENTE, PARCIAL, PAGADA\n  createdAt          DateTime  @default(now())\n\n  supplier Supplier @relation(fields: [supplierId], references: [id])\n\n  @@unique([supplierId, supplierInvoiceNum])\n  @@index([dueDate, status])\n  @@map(\"accounts_payable\")\n}\n\n// ============================================================================\n// MÓDULO 6: NÓMINA, ASISTENCIA Y COMISIONES\n// ============================================================================\n\nmodel Employee {\n  id              String          @id @default(uuid()) @db.Uuid\n  userId          String?         @unique @db.Uuid\n  branchId        String          @db.Uuid\n  documentNumber  String          @unique @db.VarChar(30)\n  fullName        String          @db.VarChar(140)\n  position        String          @db.VarChar(80)\n  contractType    String          @db.VarChar(40)\n  baseSalary      Decimal         @db.Decimal(18, 4)\n  commissionBasis CommissionBasis @default(VENTA_RECAUDADA)\n  commissionRate  Decimal         @default(0) @db.Decimal(5, 2)\n  isActive        Boolean         @default(true)\n  hiredAt         DateTime\n\n  user       User?              @relation(fields: [userId], references: [id])\n  branch     Branch             @relation(fields: [branchId], references: [id])\n  attendance AttendanceRecord[]\n  loans      EmployeeLoan[]\n  slips      PayrollSlip[]\n\n  @@map(\"employees\")\n}\n\nmodel AttendanceRecord {\n  id            String    @id @default(uuid()) @db.Uuid\n  employeeId    String    @db.Uuid\n  workDate      DateTime  @db.Date\n  clockIn       DateTime\n  clockOut      DateTime?\n  overtimeHours Decimal   @default(0) @db.Decimal(6, 2)\n  noveltyType   String?   @db.VarChar(30) // PERMISO, INCAPACIDAD, VACACIONES\n\n  employee Employee @relation(fields: [employeeId], references: [id])\n\n  @@index([employeeId, workDate])\n  @@map(\"attendance_records\")\n}\n\nmodel EmployeeLoan {\n  id               String   @id @default(uuid()) @db.Uuid\n  employeeId       String   @db.Uuid\n  totalAmount      Decimal  @db.Decimal(18, 4)\n  remainingAmount  Decimal  @db.Decimal(18, 4)\n  installmentValue Decimal  @db.Decimal(18, 4)\n  reason           String   @db.VarChar(120)\n  isActive         Boolean  @default(true)\n  createdAt        DateTime @default(now())\n\n  employee Employee @relation(fields: [employeeId], references: [id])\n\n  @@map(\"employee_loans\")\n}\n\nmodel PayrollPeriod {\n  id        String        @id @default(uuid()) @db.Uuid\n  code      String        @unique @db.VarChar(30)\n  startDate DateTime      @db.Date\n  endDate   DateTime      @db.Date\n  status    PayrollStatus @default(PRE_NOMINA)\n  closedAt  DateTime?\n\n  slips PayrollSlip[]\n\n  @@map(\"payroll_periods\")\n}\n\nmodel PayrollSlip {\n  id              String  @id @default(uuid()) @db.Uuid\n  payrollPeriodId String  @db.Uuid\n  employeeId      String  @db.Uuid\n  baseEarned      Decimal @db.Decimal(18, 4)\n  overtimeEarned  Decimal @default(0) @db.Decimal(18, 4)\n  commissionsNet  Decimal @default(0) @db.Decimal(18, 4)\n  legalDeductions Decimal @default(0) @db.Decimal(18, 4)\n  loanDeductions  Decimal @default(0) @db.Decimal(18, 4)\n  otherDeductions Decimal @default(0) @db.Decimal(18, 4)\n  netPay          Decimal @db.Decimal(18, 4)\n\n  period   PayrollPeriod @relation(fields: [payrollPeriodId], references: [id])\n  employee Employee      @relation(fields: [employeeId], references: [id])\n\n  @@unique([payrollPeriodId, employeeId])\n  @@map(\"payroll_slips\")\n}\n\n// ============================================================================\n// MÓDULO 7: AUDITORÍA INMUTABLE (APPEND-ONLY), ALERTAS ANTIFRAUDE Y OUTBOX\n// ============================================================================\n\nmodel AuditLog {\n  id           BigInt   @id @default(autoincrement())\n  userId       String?  @db.Uuid\n  supervisorId String?  @db.Uuid\n  branchId     String?  @db.Uuid\n  terminalId   String?  @db.Uuid\n  ipAddress    String?  @db.VarChar(45)\n  module       String   @db.VarChar(50)\n  action       String   @db.VarChar(60)\n  entityName   String   @db.VarChar(60)\n  entityId     String   @db.VarChar(80)\n  beforeData   Json?\n  afterData    Json?\n  metadata     Json?\n  createdAt    DateTime @default(now())\n\n  user User? @relation(fields: [userId], references: [id])\n\n  @@index([module, createdAt])\n  @@index([entityName, entityId])\n  @@index([userId, createdAt])\n  @@map(\"audit_logs\")\n}\n\nmodel FraudAlert {\n  id          String        @id @default(uuid()) @db.Uuid\n  ruleCode    String        @db.VarChar(50) // CART_ITEM_REMOVAL_SPIKE, SHRINKAGE_EXCEEDED, CASH_SHORTAGE\n  severity    FraudSeverity\n  branchId    String?       @db.Uuid\n  userId      String?       @db.Uuid\n  description String        @db.Text\n  payload     Json?\n  isResolved  Boolean       @default(false)\n  resolvedBy  String?       @db.Uuid\n  createdAt   DateTime      @default(now())\n\n  @@index([isResolved, severity, createdAt])\n  @@map(\"fraud_alerts\")\n}\n\nmodel OutboxEvent {\n  id          String    @id @default(uuid()) @db.Uuid\n  eventType   String    @db.VarChar(80)\n  aggregateId String    @db.VarChar(80)\n  payload     Json\n  processedAt DateTime?\n  retryCount  Int       @default(0)\n  createdAt   DateTime  @default(now())\n\n  @@index([processedAt, createdAt])\n  @@map(\"outbox_events\")\n}\n"
}

